import Foundation
import CryptoKit

// Independent checks of the generated bytes, not a call to the generator's implementation.
func require(_ condition: @autoclosure () -> Bool, _ message: String) throws {
    if !condition() {
        throw NSError(domain: "VerifyFixtures", code: 1, userInfo: [NSLocalizedDescriptionKey: message])
    }
}

do {
    let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
    let temporary = FileManager.default.temporaryDirectory.appendingPathComponent("poc01-fixtures-\(UUID().uuidString)")
    try FileManager.default.createDirectory(at: temporary, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: temporary) }
    let referenceURL = root.appendingPathComponent("TestData/manifest.json")
    let a = temporary.appendingPathComponent("a")
    let b = temporary.appendingPathComponent("b")
    func generate(_ directory: URL) throws -> Int32 {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/xcrun")
        process.arguments = ["swift", "-module-cache-path", temporary.appendingPathComponent("cache").path,
                             root.appendingPathComponent("Scripts/GenerateFixtures.swift").path,
                             directory.path, referenceURL.path]
        try process.run()
        process.waitUntilExit()
        return process.terminationStatus
    }
    let firstStatus = try generate(a)
    let secondStatus = try generate(b)
    try require(firstStatus == 0 && secondStatus == 0, "Generator failed")
    let reference = try Data(contentsOf: referenceURL)
    let manifestA = try Data(contentsOf: a.appendingPathComponent("manifest.json"))
    let manifestB = try Data(contentsOf: b.appendingPathComponent("manifest.json"))
    try require(reference == manifestA && manifestA == manifestB, "Manifest bytes differ")
    let object = try JSONSerialization.jsonObject(with: reference) as! [String: Any]
    let entries = object["files"] as! [[String: Any]]
    try require(entries.count == 7, "Expected seven fixtures")
    var expected: [String: Int] = ["stress-1000000-no-newline.txt": 1_000_000]
    for size in [100_000, 1_000_000, 5_000_000] {
        for label in ["lf", "crlf"] { expected["baseline-\(size)-\(label).md"] = size }
    }
    try require(Set(entries.compactMap { $0["name"] as? String }) == Set(expected.keys), "Unexpected fixture names")
    for entry in entries {
        let name = entry["name"] as! String
        let data = try Data(contentsOf: a.appendingPathComponent(name))
        let other = try Data(contentsOf: b.appendingPathComponent(name))
        try require(data == other, "Non-deterministic bytes: \(name)")
        try require(data.count == expected[name] && data.count == entry["bytes"] as? Int, "Wrong byte size: \(name)")
        let text = String(data: data, encoding: .utf8)
        try require(text != nil, "Invalid UTF-8: \(name)")
        let hash = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        try require(hash == entry["sha256"] as? String, "Wrong SHA-256: \(name)")
        let lines = data.filter { $0 == 10 }.count + ((data.last != 10 && !data.isEmpty) ? 1 : 0)
        try require(lines == entry["lines"] as? Int, "Wrong line count: \(name)")
        if name.hasSuffix("-crlf.md") {
            let stripped = text!.replacingOccurrences(of: "\r\n", with: "")
            try require(!stripped.contains("\r") && !stripped.contains("\n"), "Mixed endings: \(name)")
        } else {
            try require(!text!.contains("\r"), "Unexpected CR: \(name)")
        }
        if name.hasPrefix("stress-") {
            try require(lines == 1 && !text!.contains("\n"), "Stress file must be one unterminated line")
        } else {
            try require(text!.contains("\n\n") || text!.contains("\r\n\r\n"), "Missing empty lines")
            try require(text!.contains("Кириллица") && text!.contains("👩🏽‍💻") && text!.contains("e\u{301}"), "Missing Unicode cases")
        }
    }
    let overwriteStatus = try generate(a)
    try require(overwriteStatus != 0, "Generator must refuse to overwrite existing fixtures")
    for name in expected.keys {
        let first = try Data(contentsOf: a.appendingPathComponent(name))
        let second = try Data(contentsOf: b.appendingPathComponent(name))
        try require(first == second, "Overwrite attempt changed \(name)")
    }
    print("PASS: seven fixtures, repeatability, reference hashes, UTF-8, sizes, line endings, line counts and overwrite protection")
} catch {
    FileHandle.standardError.write(Data("FAIL: \(error.localizedDescription)\n".utf8))
    exit(1)
}
